import React, { useState } from 'react';
import { uploadAndAnalyze } from '../services/api';
import { AnalysisResult, ModelMetrics, AttackStatistics } from '../types';

interface FileUploadProps {
    onAnalysisComplete?: (result: AnalysisResult, metrics: ModelMetrics, stats: AttackStatistics) => void;
}

interface AnalysisData {
    status: string;
    filename: string;
    total_records: number;
    attacks_detected: number;
    normal_records: number;
    attack_percentage: number;
    average_confidence: number;
}

const FileUpload: React.FC<FileUploadProps> = ({ onAnalysisComplete }) => {
    const [file, setFile] = useState<File | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [uploading, setUploading] = useState(false);
    const [analyzing, setAnalyzing] = useState(false);
    const [isUploaded, setIsUploaded] = useState(false);
    const [analysisResult, setAnalysisResult] = useState<AnalysisData | null>(null);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = event.target.files?.[0];
        if (selectedFile && (selectedFile.type === 'text/csv' || selectedFile.name.endsWith('.parquet'))) {
            setFile(selectedFile);
            setError(null);
            setSuccess(null);
        } else {
            setError('Please upload a valid CSV or Parquet file.');
            setFile(null);
        }
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        e.currentTarget.classList.add('drag-over');
    };

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
        e.currentTarget.classList.remove('drag-over');
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        e.currentTarget.classList.remove('drag-over');
        const droppedFile = e.dataTransfer.files?.[0];
        if (droppedFile && (droppedFile.type === 'text/csv' || droppedFile.name.endsWith('.parquet'))) {
            setFile(droppedFile);
            setError(null);
        } else {
            setError('Please drop a valid CSV or Parquet file.');
        }
    };

    const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (!file) return;

        setLoading(true);
        setError(null);
        setSuccess(null);
        setSteps([
            { name: '📤 Upload & Analyze', status: 'loading' },
            { name: '🔮 ML Predictions', status: 'pending' },
        ]);

        try {
            // 🚀 NOUVEAU: Upload + Analyze en une seule call
            // Le backend pré-traîne déjà le modèle (detector_model.pkl)
            // Donc on fait directement: preprocessing → prédictions
            updateStep(0, 'loading');
            const analysisResponse = await uploadAndAnalyze(file);

            if (analysisResponse.status !== 'success') {
                throw new Error('Analysis failed: ' + analysisResponse.message);
            }

            setUploadedFilePath(analysisResponse.filename);
            updateStep(0, 'complete');
            setSuccess(`✅ Dataset analyzed successfully!\n📊 ${analysisResponse.total_records} records processed`);

            // Step 2: Display ML predictions
            updateStep(1, 'loading');
            const attacksDetected = analysisResponse.attacks_detected;
            const normalRecords = analysisResponse.normal_records;
            const attackPercentage = analysisResponse.attack_percentage;
            const avgConfidence = analysisResponse.average_confidence;

            updateStep(1, 'complete');
            setSuccess(prev => (prev || '') + `\n🚨 Attacks detected: ${attacksDetected} (${attackPercentage}%)\n✅ Normal traffic: ${normalRecords}\n📈 Model confidence: ${(avgConfidence * 100).toFixed(2)}%`);

            // Prepare result object for callback
            const result: AnalysisResult = {
                predictions: [],
                statistics: {
                    total_events: analysisResponse.total_records,
                    benign_count: normalRecords,
                    attack_count: attacksDetected,
                    attack_percentage: attackPercentage
                }
            };

            const metrics: ModelMetrics = {
                accuracy: avgConfidence,
                precision: avgConfidence,
                recall: avgConfidence,
                f1_score: avgConfidence
            };

            const stats: AttackStatistics = {
                total_attacks: attacksDetected,
                avg_confidence: avgConfidence
            };

            // Call the callback if provided
            if (onAnalysisComplete) {
                onAnalysisComplete(result, metrics, stats);
            }
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : 'An error occurred during analysis';
            setError(errorMessage);
            console.error('Error during analysis:', error);

            // Mark current step as error
            for (let i = 0; i < steps.length; i++) {
                if (steps[i].status === 'loading') {
                    updateStep(i, 'error');
                    break;
                }
            }
        } finally {
            setLoading(false);
        }
    };

    const getStepIcon = (status: StepStatus) => {
        switch (status) {
            case 'complete':
                return '✓';
            case 'error':
                return '✗';
            case 'loading':
                return '⟳';
            default:
                return '○';
        }
    };

    const completedSteps = steps.filter(s => s.status === 'complete').length;
    const progressPercent = (completedSteps / steps.length) * 100;

    return (
        <div>
            <form onSubmit={handleSubmit}>
                {/* Drag and Drop Area */}
                <div 
                    className="file-upload-area"
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                >
                    <div className="upload-icon">▲</div>
                    <h2 className="upload-title">Upload Your Dataset</h2>
                    <p className="upload-subtitle">Drag and drop your file here or click to select</p>
                    <p className="file-extensions">Supported: .csv or .parquet</p>
                    <input
                        type="file"
                        accept=".csv,.parquet"
                        onChange={handleFileChange}
                        disabled={loading}
                        id="file-input"
                        style={{ display: 'none' }}
                    />
                    <label htmlFor="file-input" style={{ cursor: 'pointer' }}>
                        <button 
                            type="button"
                            className="btn btn-primary"
                            disabled={loading}
                            onClick={() => document.getElementById('file-input')?.click()}
                        >
                            Choose File
                        </button>
                    </label>
                    {file && (
                        <p className="upload-success">✓ {file.name}</p>
                    )}
                </div>

                {/* Submit Button */}
                <div style={{ marginBottom: '24px', marginTop: '24px' }}>
                    <button
                        type="submit"
                        className="btn btn-primary"
                        style={{ width: '100%' }}
                        disabled={!file || loading}
                    >
                        {loading ? 'Analyzing...' : 'Upload & Analyze'}
                    </button>
                </div>
            </form>

            {/* Steps Progress */}
            {loading && (
                <div className="card" style={{ marginBottom: '24px', backgroundColor: 'rgba(102, 126, 234, 0.05)' }}>
                    <div style={{ padding: '16px' }}>
                        <h3 style={{ marginBottom: '24px', fontWeight: 'bold' }}>Analysis Progress</h3>
                        <div className="step-list">
                            {steps.map((step, index) => (
                                <div key={index} className="step-item">
                                    <span className={`step-icon step-icon-${step.status}`}>
                                        {getStepIcon(step.status)}
                                    </span>
                                    <span className={step.status === 'loading' ? 'step-name-loading' : 'step-name'}>
                                        {step.name}
                                    </span>
                                </div>
                            ))}
                        </div>
                        <div className="progress-bar" style={{ marginTop: '16px' }}>
                            <div 
                                className="progress-fill" 
                                style={{ width: `${progressPercent}%` }}
                            ></div>
                        </div>
                    </div>
                </div>
            )}

            {/* Error Alert */}
            {error && (
                <div className="alert alert-error" style={{ marginBottom: '24px' }}>
                    <span>{error}</span>
                    <button 
                        className="alert-close"
                        onClick={() => setError(null)}
                        type="button"
                    >
                        ✕
                    </button>
                </div>
            )}

            {/* Success Alert */}
            {success && (
                <div className="alert alert-success" style={{ marginBottom: '24px', whiteSpace: 'pre-wrap' }}>
                    <span>{success}</span>
                    <button 
                        className="alert-close"
                        onClick={() => setSuccess(null)}
                        type="button"
                    >
                        ✕
                    </button>
                </div>
            )}

            {/* Uploaded File Path */}
            {uploadedFilePath && (
                <div className="card" style={{ backgroundColor: 'rgba(102, 126, 234, 0.05)' }}>
                    <div style={{ padding: '16px' }}>
                        <p style={{ fontSize: '0.875rem', color: '#666' }}>
                            <strong>Uploaded File Path:</strong>
                        </p>
                        <p style={{ marginTop: '8px', fontSize: '0.875rem', wordBreak: 'break-all' }}>
                            {uploadedFilePath}
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default FileUpload;
